printf '\n    %s%s%s\n\n' "$BOLD" "$SITE" "$RESET"
copy "$SITE" "Site URL"
pause "貼好 Site URL 了？按 Enter 拿下一個要貼的"
printf '\n'
say "${BOLD}Redirect URLs${RESET} 按「Add URL」加這一行（已複製）："
printf '\n    %s%s**%s\n\n' "$BOLD" "$SITE" "$RESET"
copy "${SITE}**" "Redirect URL"
note "本機開發如果也要能登入，再加一行 http://localhost:*/**"
step "Save changes。"
printf '\n'
pause "存好了？按 Enter，我來試打一次登入的入口"
