# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Supabase — 建表（戰績與帳號欄位）"
say "players 要多幾欄放帳號 id 與頭像，另外新增一張 results 存每一場的戰績。"
say "SQL 已經寫好在 supabase/migrations/0004_auth.sql，整份放進剪貼簿了。"
printf '\n'
if [[ -f "${REPO_ROOT}/supabase/migrations/0004_auth.sql" ]]; then
