  printf '\n'
  printf '  %s✓ 切換完成%s\n' "$GREEN" "$RESET"
  note "開一次 ${SITE} 確認登入頁出得來。"
else
  SKIPPED+=("切換上線：npx supabase functions deploy game --project-ref ${REF}")
